using HammerTrackPro2.Models;
using HammerTrackPro2.Services;
using HammerTrackPro2.ViewModels;

namespace HammerTrackPro2.Forms;

public sealed class AuctionSettlementForm:Form
{
    internal const int MetricColumnCount=6;
    internal const int MetricRowCount=2;
    internal const int ScrollableContentHeight=880;
    private static readonly Color Navy=Color.FromArgb(24,50,74);
    private static readonly Color Blue=Color.FromArgb(24,96,150);
    private static readonly Color Gold=Color.FromArgb(224,168,54);
    private static readonly Color Canvas=Color.FromArgb(242,245,248);
    private readonly AuctionSettlementViewModel _viewModel;
    private readonly DataGridView _grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=false,AllowUserToAddRows=false,AllowUserToDeleteRows=false,MultiSelect=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect};
    private readonly Label _auctionHeading=new(){Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft};
    private readonly Label _status=new(){Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft};
    private readonly ComboBox _category=new(){DropDownStyle=ComboBoxStyle.DropDownList,DataSource=new[]{"Clerk","Auctioneer","Floor Help","Kitchen Help"},Width=145};
    private readonly TextBox _payee=new(){Width=190,PlaceholderText="Person or business"};
    private readonly NumericUpDown _amount=new(){DecimalPlaces=2,Maximum=1000000,Width=125,ThousandsSeparator=true};
    private readonly ComboBox _method=new(){DropDownStyle=ComboBoxStyle.DropDown,DataSource=new[]{"Cash","Check","Card","ACH","Other"},Width=120};
    private readonly TextBox _notes=new(){Width=230,PlaceholderText="Check number or notes"};
    private readonly Button _fullScreenButton=new(){Text="Full Screen"};
    private readonly Dictionary<string,Label> _values=[];
    private bool _fullScreen;

    public AuctionSettlementForm(ICashierService service)
    {
        _viewModel=new AuctionSettlementViewModel(service);
        Text="HammerTrack Pro - End-of-Night Settlement";StartPosition=FormStartPosition.CenterParent;Width=1380;Height=850;MinimumSize=new Size(1100,720);BackColor=Canvas;KeyPreview=true;
        ConfigureGrid();
        var header=BuildHeader();
        var summaryTitle=SectionHeader("AUCTION FINANCIAL SUMMARY","Live current-auction totals. Choose Refresh Totals whenever you want to reload the latest activity.");
        var summary=BuildSummary();
        var entryTitle=SectionHeader("STAFF & OPERATING PAYMENT","Record clerk, auctioneer, floor-help, or kitchen-help payments. Every entry remains in the audit ledger.");
        var entry=BuildEntry();
        var ledgerTitle=SectionHeader("PAYMENT LEDGER","Select an incorrect payment and choose Void Selected. Voids remain visible for a complete audit trail.");
        var ledgerPanel=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(12,0,12,10)};ledgerPanel.Controls.Add(_grid);
        var statusBar=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(14,3,14,3)};_status.Font=new Font("Segoe UI",9.5F,FontStyle.Bold);_status.ForeColor=Navy;statusBar.Controls.Add(_status);
        var layout=new TableLayoutPanel{Dock=DockStyle.Top,Height=ScrollableContentHeight,RowCount=8,ColumnCount=1,Padding=new Padding(12,0,12,12),BackColor=Canvas};
        layout.RowStyles.Add(new RowStyle(SizeType.Absolute,78));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,62));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,196));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,62));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,118));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,62));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,262));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,40));
        layout.Controls.Add(header,0,0);layout.Controls.Add(summaryTitle,0,1);layout.Controls.Add(summary,0,2);layout.Controls.Add(entryTitle,0,3);layout.Controls.Add(entry,0,4);layout.Controls.Add(ledgerTitle,0,5);layout.Controls.Add(ledgerPanel,0,6);layout.Controls.Add(statusBar,0,7);
        var scrollHost=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Canvas};scrollHost.Controls.Add(layout);Controls.Add(scrollHost);
        _fullScreenButton.Click+=(_,_)=>ToggleFullScreen();KeyDown+=(_,e)=>HandleShortcut(e);_viewModel.Refresh();RefreshReport();
    }

    private Control BuildHeader(){var panel=new Panel{Dock=DockStyle.Fill,BackColor=Navy,Padding=new Padding(20,10,16,10)};var brand=new Label{Text="HAMMERTRACK PRO",Dock=DockStyle.Left,Width=300,TextAlign=ContentAlignment.MiddleLeft,Font=new Font("Segoe UI",20F,FontStyle.Bold),ForeColor=Color.White};var subtitle=new Label{Text="END-OF-NIGHT",Dock=DockStyle.Left,Width=190,TextAlign=ContentAlignment.MiddleLeft,Font=new Font("Segoe UI",11F,FontStyle.Bold),ForeColor=Gold};StyleButton(_fullScreenButton,true);_fullScreenButton.Dock=DockStyle.Right;_auctionHeading.Font=new Font("Segoe UI",11F,FontStyle.Bold);_auctionHeading.ForeColor=Color.White;_auctionHeading.Padding=new Padding(20,0,20,0);panel.Controls.Add(_fullScreenButton);panel.Controls.Add(_auctionHeading);panel.Controls.Add(subtitle);panel.Controls.Add(brand);return panel;}
    private static Control SectionHeader(string title,string subtitle){var panel=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(14,8,14,4),Margin=new Padding(0,8,0,0)};panel.Controls.Add(new Label{Text=subtitle,Dock=DockStyle.Bottom,Height=22,Font=new Font("Segoe UI",8.5F),ForeColor=Color.FromArgb(90,100,110)});panel.Controls.Add(new Label{Text=title,Dock=DockStyle.Top,Height=25,Font=new Font("Segoe UI",12F,FontStyle.Bold),ForeColor=Navy});return panel;}
    private Control BuildSummary()
    {
        var panel=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=MetricColumnCount,RowCount=MetricRowCount,BackColor=Canvas,Padding=new Padding(0,4,0,4)};for(var i=0;i<MetricColumnCount;i++)panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100F/MetricColumnCount));for(var i=0;i<MetricRowCount;i++)panel.RowStyles.Add(new RowStyle(SizeType.Percent,100F/MetricRowCount));
        AddMetric(panel,"Hammer Sales",nameof(AuctionSettlementReport.HammerSales),0,0);AddMetric(panel,"Buyer Premiums",nameof(AuctionSettlementReport.BuyerPremiums),1,0);AddMetric(panel,"Card Fees",nameof(AuctionSettlementReport.CreditCardFees),2,0);AddMetric(panel,"Sales Tax",nameof(AuctionSettlementReport.SalesTaxCollected),3,0);AddMetric(panel,"Invoice Total",nameof(AuctionSettlementReport.InvoiceTotal),4,0);AddMetric(panel,"Buyer Payments",nameof(AuctionSettlementReport.InvoiceAmountPaid),5,0);
        AddMetric(panel,"Still Unpaid",nameof(AuctionSettlementReport.InvoiceBalanceUnpaid),0,1,true);AddMetric(panel,"Seller Gross",nameof(AuctionSettlementReport.ConsignorGrossSales),1,1);AddMetric(panel,"Seller Commission",nameof(AuctionSettlementReport.ConsignorCommissions),2,1);AddMetric(panel,"Seller Payouts",nameof(AuctionSettlementReport.ConsignorPayouts),3,1);AddMetric(panel,"Staff Payments",nameof(AuctionSettlementReport.StaffPayments),4,1);AddMetric(panel,"NET CASH MOVEMENT",nameof(AuctionSettlementReport.NetCashMovement),5,1,false,true);return panel;
    }
    private void AddMetric(TableLayoutPanel parent,string title,string key,int column,int row,bool warning=false,bool accent=false){var card=new Panel{Dock=DockStyle.Fill,BackColor=accent?Navy:Color.White,Margin=new Padding(4),Padding=new Padding(12,6,12,5)};var value=new Label{Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,Font=new Font("Segoe UI",15F,FontStyle.Bold),ForeColor=accent?Gold:warning?Color.FromArgb(166,48,48):Navy};var caption=new Label{Text=title,Dock=DockStyle.Top,Height=20,Font=new Font("Segoe UI",8.5F,FontStyle.Bold),ForeColor=accent?Color.White:Color.FromArgb(85,95,105)};card.Controls.Add(value);card.Controls.Add(caption);parent.Controls.Add(card,column,row);_values[key]=value;}
    private Control BuildEntry(){var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,WrapContents=true,BackColor=Color.White,Padding=new Padding(12,6,12,8)};AddField(flow,"Category",_category);AddField(flow,"Payee",_payee);AddField(flow,"Amount",_amount);AddField(flow,"Payment Method",_method);AddField(flow,"Reference / Notes",_notes);flow.Controls.Add(Button("Record Payment",Record,true));flow.Controls.Add(Button("Void Selected",Void,false,true));flow.Controls.Add(Button("Refresh Totals",RefreshFromService));flow.Controls.Add(Button("Print Report",Print));return flow;}
    private static void AddField(FlowLayoutPanel panel,string label,Control input){var holder=new TableLayoutPanel{AutoSize=true,RowCount=2,ColumnCount=1,Margin=new Padding(4,0,8,4)};holder.Controls.Add(new Label{Text=label,AutoSize=true,Font=new Font("Segoe UI",8.5F,FontStyle.Bold),ForeColor=Navy},0,0);input.Font=new Font("Segoe UI",10.5F);input.Height=34;holder.Controls.Add(input,0,1);panel.Controls.Add(holder);}
    private static Button Button(string text,Action action,bool accent=false,bool danger=false){var button=new Button{Text=text};StyleButton(button,accent,danger);button.Click+=(_,_)=>Execute(action);return button;}
    private static void StyleButton(Button button,bool accent=false,bool danger=false){button.AutoSize=false;button.Width=145;button.Height=44;button.Margin=new Padding(5,20,5,5);button.FlatStyle=FlatStyle.Flat;button.FlatAppearance.BorderSize=1;button.BackColor=danger?Color.FromArgb(166,48,48):accent?Gold:Blue;button.ForeColor=accent?Navy:Color.White;button.FlatAppearance.BorderColor=danger?Color.FromArgb(125,32,32):accent?Gold:Color.FromArgb(15,72,112);button.Font=new Font("Segoe UI",10F,FontStyle.Bold);button.Cursor=Cursors.Hand;}
    private void ConfigureGrid(){_grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(StaffPayment.PaidUtc),HeaderText="Date / Time",FillWeight=95,DefaultCellStyle=new DataGridViewCellStyle{Format="g"}});_grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(StaffPayment.Category),HeaderText="Category",FillWeight=80});_grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(StaffPayment.Payee),HeaderText="Payee",FillWeight=125});_grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(StaffPayment.Amount),HeaderText="Amount",FillWeight=70,DefaultCellStyle=new DataGridViewCellStyle{Format="C2"}});_grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(StaffPayment.Method),HeaderText="Method",FillWeight=65});_grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(StaffPayment.Notes),HeaderText="Reference / Notes",FillWeight=140});_grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=nameof(StaffPayment.VoidReason),HeaderText="Void Reason",FillWeight=110});_grid.BackgroundColor=Color.White;_grid.BorderStyle=BorderStyle.None;_grid.RowHeadersVisible=false;_grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;_grid.RowTemplate.Height=34;_grid.ColumnHeadersHeight=40;_grid.EnableHeadersVisualStyles=false;_grid.ColumnHeadersDefaultCellStyle.BackColor=Navy;_grid.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;_grid.ColumnHeadersDefaultCellStyle.Font=new Font("Segoe UI",10F,FontStyle.Bold);_grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(214,232,245);_grid.DefaultCellStyle.SelectionForeColor=Navy;_grid.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(246,249,251);}
    private void HandleShortcut(KeyEventArgs e){if(e.KeyCode==Keys.F11){ToggleFullScreen();e.Handled=true;}else if(e.KeyCode==Keys.Escape&&_fullScreen){ToggleFullScreen();e.Handled=true;}else if(e.Control&&e.KeyCode==Keys.P){Print();e.SuppressKeyPress=true;}else if(e.KeyCode==Keys.F5){RefreshFromService();e.Handled=true;}}
    private void ToggleFullScreen(){_fullScreen=!_fullScreen;FormBorderStyle=_fullScreen?FormBorderStyle.None:FormBorderStyle.Sizable;WindowState=_fullScreen?FormWindowState.Maximized:FormWindowState.Normal;_fullScreenButton.Text=_fullScreen?"Exit Full Screen":"Full Screen";}
    private void RefreshFromService(){_viewModel.Refresh();RefreshReport();_status.Text="Totals and payment ledger refreshed.";}
    private void RefreshReport(){var r=_viewModel.Report;_auctionHeading.Text=$"{r.AuctionNumber}  |  {r.AuctionName}";Set(nameof(r.HammerSales),r.HammerSales);Set(nameof(r.BuyerPremiums),r.BuyerPremiums);Set(nameof(r.CreditCardFees),r.CreditCardFees);Set(nameof(r.SalesTaxCollected),r.SalesTaxCollected);Set(nameof(r.InvoiceTotal),r.InvoiceTotal);Set(nameof(r.InvoiceAmountPaid),r.InvoiceAmountPaid);Set(nameof(r.InvoiceBalanceUnpaid),r.InvoiceBalanceUnpaid);Set(nameof(r.ConsignorPayouts),r.ConsignorPayouts);Set(nameof(r.ConsignorGrossSales),r.ConsignorGrossSales);Set(nameof(r.ConsignorCommissions),r.ConsignorCommissions);Set(nameof(r.StaffPayments),r.StaffPayments);Set(nameof(r.NetCashMovement),r.NetCashMovement);_grid.DataSource=null;_grid.DataSource=r.StaffLedger.ToList();_grid.ClearSelection();_status.Text=$"Current auction totals loaded. {r.StaffLedger.Count} staff/operating ledger entr{(r.StaffLedger.Count==1?"y":"ies")}.";}
    private void Set(string key,decimal value)=>_values[key].Text=value.ToString("C2");
    private void Record(){var category=_category.Text;var payee=_payee.Text.Trim();var amount=_amount.Value;_viewModel.RecordStaffPayment(category,payee,amount,_method.Text,_notes.Text);_payee.Clear();_amount.Value=0;_notes.Clear();RefreshReport();_status.Text=$"Recorded {category} payment of {amount:C2} to {payee}.";}
    private void Void(){if(_grid.CurrentRow?.DataBoundItem is not StaffPayment payment){MessageBox.Show("Select a payment in the ledger before choosing Void Selected.","End-of-Night Settlement",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}var reason=Microsoft.VisualBasic.Interaction.InputBox($"Enter the required reason for voiding the {payment.Amount:C2} payment to {payment.Payee}.","Void Staff Payment");if(string.IsNullOrWhiteSpace(reason))return;if(MessageBox.Show($"Void the {payment.Amount:C2} payment to {payment.Payee}? The original entry will remain in the audit ledger.","Confirm Void",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;_viewModel.VoidStaffPayment(payment,reason);RefreshReport();_status.Text=$"Payment to {payment.Payee} was voided. The original and correction remain in the ledger.";}
    private void Print(){using var document=new AuctionSettlementPrinter().CreateDocument(_viewModel.Report);using var preview=new PrintPreviewDialog{Document=document,Text="Print Preview - End-of-Night Settlement",Width=1100,Height=800,StartPosition=FormStartPosition.CenterParent,UseAntiAlias=true};preview.ShowDialog(this);}
    private static void Execute(Action action){try{action();}catch(Exception exception){MessageBox.Show(exception.Message,"End-of-Night Settlement",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}
